import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const words = second.split(" ");

let best = words[0];
for (const w of words) {
  // 「より長い」ときだけ更新すれば、同じ長さでは最初のものが残る
  if (w.length > best.length) best = w;
}
console.log(best);
